WITH customer_summary AS (SELECT customer_id, ROUND((100 * SUM(CASE WHEN plan = 'basic' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_basic, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee FROM subscriptions GROUP BY customer_id) SELECT customers.id, customers.credit_limit, customer_summary.pct_basic, customer_summary.avg_monthly_fee FROM customers LEFT JOIN customer_summary ON customers.id = customer_summary.customer_id ORDER BY pct_basic DESC
